"""Trusted evaluation evidence must be generated by an isolated two-stage gate."""

from __future__ import annotations

import hashlib
import inspect
import json
import subprocess
from pathlib import Path
from typing import cast
from unittest.mock import patch

import pytest

from anva.skills.trusted_evals import (
    TrustedEvalError,
    _host_version,
    grade_evaluation,
    main,
    prepare_evaluation,
    run_evaluation,
)

ROOT = Path(__file__).parents[2]
PACKAGE_ROOT = ROOT / "packages" / "anva-skills"
PUBLIC_INPUTS = ROOT / "tests" / "skill_evals" / "public"


def _prepare(tmp_path: Path, host: str) -> Path:
    evidence = tmp_path / f"evidence-{host}"
    prepare_evaluation(
        host=host,
        workflow="anva-prepare",
        package_root=PACKAGE_ROOT,
        task=PUBLIC_INPUTS / "forward-prepare-task.txt",
        transcript=PUBLIC_INPUTS / "synthetic-mcp-transcript.json",
        evidence_directory=evidence,
        commit_sha="6" * 40,
    )
    return evidence


def _valid_prepare_output() -> dict[str, object]:
    fixture = json.loads(
        (ROOT / "tests" / "fixtures" / "skill-evals" / "messy-knowledge.json").read_text(
            encoding="utf-8"
        )
    )
    output = fixture["structured_output"]
    assert isinstance(output, dict)
    return output


def _rewrite_manifest(evidence: Path, payload: dict[str, object]) -> None:
    path = evidence / "isolation_manifest.json"
    path.chmod(0o600)
    path.write_text(json.dumps(payload, sort_keys=True), encoding="utf-8")
    path.chmod(0o444)


def _seal_fake_run(
    evidence: Path,
    *,
    output: dict[str, object] | None = None,
) -> str:
    output_bytes = (
        json.dumps(output or _valid_prepare_output(), indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    output_hash = hashlib.sha256(output_bytes).hexdigest()
    stdout = b'{"synthetic":"raw host stdout"}'
    stderr = b""
    (evidence / "structured-output.json").write_bytes(output_bytes)
    (evidence / "raw-host-stdout.bin").write_bytes(stdout)
    (evidence / "raw-host-stderr.bin").write_bytes(stderr)
    manifest = json.loads((evidence / "isolation_manifest.json").read_text(encoding="utf-8"))
    run_record = {
        "format_version": 1,
        "status": "OUTPUT_SEALED_UNGRADED",
        "host": "codex",
        "host_version": "codex-cli TEST",
        "input_artifact_sha256": manifest["input_artifact_sha256"],
        "structured_output_sha256": output_hash,
        "stdout_sha256": hashlib.sha256(stdout).hexdigest(),
        "stderr_sha256": hashlib.sha256(stderr).hexdigest(),
        "sealed_at": "2026-07-31T00:00:00+00:00",
    }
    (evidence / "run-record.json").write_text(
        json.dumps(run_record, sort_keys=True),
        encoding="utf-8",
    )
    for name in (
        "structured-output.json",
        "raw-host-stdout.bin",
        "raw-host-stderr.bin",
        "run-record.json",
    ):
        (evidence / name).chmod(0o444)
    return output_hash


def _grading_files(tmp_path: Path) -> tuple[Path, Path]:
    oracle = tmp_path / "oracle.json"
    grader = tmp_path / "grader.json"
    oracle.write_text(
        json.dumps(
            {
                "workflow": "anva-prepare",
                "expected_values": {"/status": "GROUNDED"},
                "forbidden_strings": ["ORACLE-SENTINEL"],
            }
        ),
        encoding="utf-8",
    )
    grader.write_text(
        json.dumps(
            {
                "grader_id": "deterministic-v1",
                "schema_points": 60,
                "oracle_points": 40,
                "passing_score": 100,
            }
        ),
        encoding="utf-8",
    )
    return oracle, grader


