@pytest.mark.unit
def test_grade_records_all_auditable_hashes_after_output_seal(tmp_path: Path) -> None:
    evidence = tmp_path / "evidence"
    prepare_evaluation(
        host="codex",
        workflow="anva-prepare",
        package_root=PACKAGE_ROOT,
        task=PUBLIC_INPUTS / "forward-prepare-task.txt",
        transcript=PUBLIC_INPUTS / "synthetic-mcp-transcript.json",
        evidence_directory=evidence,
        commit_sha="7" * 40,
    )
    fixture = json.loads(
        (ROOT / "tests" / "fixtures" / "skill-evals" / "messy-knowledge.json").read_text(
            encoding="utf-8"
        )
    )
    output_bytes = (
        json.dumps(fixture["structured_output"], indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    output_hash = hashlib.sha256(output_bytes).hexdigest()
    stdout = b'{"synthetic":"raw host stdout"}'
    stderr = b""
    (evidence / "structured-output.json").write_bytes(output_bytes)
    (evidence / "raw-host-stdout.bin").write_bytes(stdout)
    (evidence / "raw-host-stderr.bin").write_bytes(stderr)
    run_record = {
        "format_version": 1,
        "status": "OUTPUT_SEALED_UNGRADED",
        "host": "codex",
        "host_version": "codex-cli TEST",
        "input_artifact_sha256": json.loads(
            (evidence / "isolation_manifest.json").read_text(encoding="utf-8")
        )["input_artifact_sha256"],
        "structured_output_sha256": output_hash,
        "stdout_sha256": hashlib.sha256(stdout).hexdigest(),
        "stderr_sha256": hashlib.sha256(stderr).hexdigest(),
        "sealed_at": "2026-07-31T00:00:00+00:00",
    }
    (evidence / "run-record.json").write_text(
        json.dumps(run_record, sort_keys=True),
        encoding="utf-8",
    )
    for name in (
        "structured-output.json",
        "raw-host-stdout.bin",
        "raw-host-stderr.bin",
        "run-record.json",
    ):
        (evidence / name).chmod(0o444)
    oracle = tmp_path / "oracle.json"
    grader = tmp_path / "grader.json"
    oracle.write_text(
        json.dumps(
            {
                "workflow": "anva-prepare",
                "expected_values": {"/status": "GROUNDED"},
                "forbidden_strings": ["ORACLE-SENTINEL"],
            }
        ),
        encoding="utf-8",
    )
    grader.write_text(
        json.dumps(
            {
                "grader_id": "deterministic-v1",
                "schema_points": 60,
                "oracle_points": 40,
                "passing_score": 100,
            }
        ),
        encoding="utf-8",
    )

    grade = grade_evaluation(
        evidence_directory=evidence,
        oracle=oracle,
        grader=grader,
    )

    assert grade["status"] == "PASSED"
    assert grade["evidence_class"] == "trusted-live-model-release-evidence"
    assert grade["schema_valid"] is True
    assert grade["score"] == 100
    assert grade["structured_output_sha256"] == output_hash
    for field in (
        "isolation_manifest_sha256",
        "input_artifact_sha256",
        "raw_stdout_sha256",
        "raw_stderr_sha256",
        "oracle_sha256",
        "grader_sha256",
        "gate_sha256",
        "host_version_sha256",
    ):
        value = grade[field]
        assert isinstance(value, str)
        assert len(value) == 64
    assert (evidence / "grade-record.json").stat().st_mode & 0o222 == 0


