@pytest.mark.unit
def test_grade_rejects_sealed_output_and_raw_stream_tampering(tmp_path: Path) -> None:
    evidence = _prepare(tmp_path, "codex")
    _seal_fake_run(evidence)
    oracle, grader = _grading_files(tmp_path)
    output = evidence / "structured-output.json"
    output.chmod(0o600)
    output.write_text("{}", encoding="utf-8")
    with pytest.raises(TrustedEvalError, match="Structured output changed"):
        grade_evaluation(
            evidence_directory=evidence,
            oracle=oracle,
            grader=grader,
        )

    raw_evidence = tmp_path / "raw-tamper"
    raw_evidence = _prepare(raw_evidence, "codex")
    _seal_fake_run(raw_evidence)
    stdout = raw_evidence / "raw-host-stdout.bin"
    stdout.chmod(0o600)
    stdout.write_text("tampered", encoding="utf-8")
    with pytest.raises(TrustedEvalError, match="Raw host output changed"):
        grade_evaluation(
            evidence_directory=raw_evidence,
            oracle=oracle,
            grader=grader,
        )

    mismatched = _prepare(tmp_path / "record-mismatch", "codex")
    _seal_fake_run(mismatched)
    run_path = mismatched / "run-record.json"
    run_payload = json.loads(run_path.read_text(encoding="utf-8"))
    run_payload["input_artifact_sha256"] = "0" * 64
    run_path.chmod(0o600)
    run_path.write_text(json.dumps(run_payload), encoding="utf-8")
    with pytest.raises(TrustedEvalError, match="does not match"):
        grade_evaluation(
            evidence_directory=mismatched,
            oracle=oracle,
            grader=grader,
        )


@pytest.mark.unit
@pytest.mark.parametrize(
    ("target", "payload", "message"),
    [
        ("oracle", {"unknown": True}, "Oracle fields"),
        (
            "oracle",
            {
                "workflow": "anva-build",
                "expected_values": {},
                "forbidden_strings": [],
            },
            "workflow",
        ),
        (
            "oracle",
            {
                "workflow": "anva-prepare",
                "expected_values": [],
                "forbidden_strings": [],
            },
            "checks",
        ),
        ("grader", {"unknown": True}, "Grader fields"),
        (
            "grader",
            {
                "grader_id": "",
                "schema_points": 70,
                "oracle_points": 40,
                "passing_score": 100,
            },
            "score configuration",
        ),
    ],
)
def test_grade_rejects_invalid_oracle_and_grader_contracts(
    tmp_path: Path,
    target: str,
    payload: dict[str, object],
    message: str,
) -> None:
    evidence = _prepare(tmp_path, "codex")
    _seal_fake_run(evidence)
    oracle, grader = _grading_files(tmp_path)
    selected = oracle if target == "oracle" else grader
    selected.write_text(json.dumps(payload), encoding="utf-8")

    with pytest.raises(TrustedEvalError, match=message):
        grade_evaluation(
            evidence_directory=evidence,
            oracle=oracle,
            grader=grader,
        )


@pytest.mark.unit
def test_failed_schema_and_oracle_grade_is_recorded_without_release_claim(
    tmp_path: Path,
) -> None:
    evidence = _prepare(tmp_path, "codex")
    invalid_output = _valid_prepare_output()
    invalid_output["status"] = "INVALID"
    _seal_fake_run(evidence, output=invalid_output)
    oracle, grader = _grading_files(tmp_path)
    oracle.write_text(
        json.dumps(
            {
                "workflow": "anva-prepare",
                "expected_values": {
                    "/status": "GROUNDED",
                    "/missing/value": True,
                },
                "forbidden_strings": ["Security review is mandatory."],
            }
        ),
        encoding="utf-8",
    )

    grade = grade_evaluation(
        evidence_directory=evidence,
        oracle=oracle,
        grader=grader,
    )

    assert grade["status"] == "FAILED"
    assert grade["evidence_class"] == "trusted-live-model-failed-evaluation"
    assert grade["schema_valid"] is False
    assert grade["score"] == 0


@pytest.mark.unit
def test_command_line_gate_reports_prepare_error_and_dispatches_run(
    tmp_path: Path,
    capsys: pytest.CaptureFixture[str],
) -> None:
    error_code = main(
        [
            "prepare",
            "--host",
            "codex",
            "--workflow",
            "anva-prepare",
            "--package-root",
            str(PACKAGE_ROOT),
            "--task",
            str(PUBLIC_INPUTS / "forward-prepare-task.txt"),
            "--transcript",
            str(PUBLIC_INPUTS / "synthetic-mcp-transcript.json"),
            "--evidence-directory",
            str(tmp_path / "evidence"),
            "--commit-sha",
            "invalid",
        ]
    )
    assert error_code == 2
    assert json.loads(capsys.readouterr().out)["status"] == "ERROR"

    with patch(
        "anva.skills.trusted_evals.run_evaluation",
        return_value={"status": "NOT_RUN"},
    ) as run:
        run_code = main(
            [
                "run",
                "--evidence-directory",
                str(tmp_path / "prepared"),
                "--timeout-seconds",
                "30",
            ]
        )
    assert run_code == 0
    run.assert_called_once()
